export async function execMetadata(hostArgs: Record<string, unknown>) {
  {
    const info = hostArgs as Record<string, any>;
    info.user_agent = legacyCompat.userAgent();
    for (const c of (info.user_agent_cookies ?? []) as { name: string; value: string; domain: string; path: string }[]) {
      info.user_agent.cookie_jar.add(c);
    }
    const headers = (info.user_agent_headers ?? {}) as Record<string, string>;
    if (Object.keys(headers).length > 0) {
      info.user_agent.on("start", (_ua: any, tx: any) => {
        for (const [name, value] of Object.entries(headers)) tx.req.headers.header(name, value);
      });
    }
  }
  interface ExecMetadataInfo extends Required<Pick<MetadataHostArgs, "arg" | "existing_tags" | "file_path" | "customargs">> {
    user_agent: LegacyUserAgent;
    user_agent_cookies?: LegacyCookie[];
  }
  let match: RegExpMatchArray | null;
  // (shift) discarded positional arg — legacy Perl-OOP invocant/first @_ slot
  let lrr_info = hostArgs as unknown as ExecMetadataInfo;
  let ua = lrr_info["user_agent"];
  // Was `hostArgs.arg` — that's the oneshot gallery URL, not param1's persisted value.
  // customargs[0]/[1] are the real settings-page values for param1/param2.
  let add_uploaded = (lrr_info.customargs?.[0] as boolean | undefined) ?? false;
  let prefer_japanese_title = (lrr_info.customargs?.[1] as boolean | undefined) ?? false;
  let logger = legacyCompat.getLogger("nHentai", "plugins");
  let galleryID = "";
  if ((match = (lrr_info["arg"] ?? "").match(/.*\/g\/([0-9]+).*/))) {
    galleryID = match[1];
    logger.debug(`Skipping search and using gallery ${galleryID} from oneshot args`);
  } else if (
    // No `/g` here: with the global flag `.match()` returns whole-match strings and `match[1]` is
    // `undefined`, so the source tag was found and then silently dropped — the archive was told
    // "No matching nHentai Gallery Found!" while its own tags named the gallery.
    (match = (lrr_info["existing_tags"] ?? "").match(
      /source:\s*(?:https?:\/\/)?nhentai\.net\/g\/([0-9]+)/i,
    ))
  ) {
    galleryID = match[1];
    logger.debug(`Skipping search and using gallery ${galleryID} from source tag`);
  } else {
    // No oneshot argument and no source tag: search on the archive's own name. The stored title
    // comes first because a hash-layout library keeps the readable name in the record, not in the
    // file name — `/content/ab/<id>.zip` parses to nothing searchable.
    for (let candidate of search_candidates(lrr_info)) {
      logger.debug(`Searching gallery by title: ${candidate}`);
      galleryID = await search_gallery_id(candidate, ua);
      if (galleryID) break;
    }
  }
  if (! galleryID) {
    let message = "No matching nHentai Gallery Found!";
    logger.info(message);
    throw new PluginSkipException(message);
  }
  logger.debug(`Detected nHentai gallery ID is ${galleryID}`);
  let hashdata = await get_tags_from_nh(galleryID, ua, add_uploaded, prefer_japanese_title);
  logger.info("Sending the following tags to LRR: " + hashdata["tags"]);
  return hashdata;
}

async function get_search_json(...args: any[]) {
  let [title, ua] = args.slice(0);
  let logger = legacyCompat.getLogger("nHentai", "plugins");
  let URL = "https://nhentai.net/api/v2/search?query=" + encodeURIComponent(title);
  let res = (await ua.get(URL)).result;
  if (res.is_error) {
    let code = res.code;
    throw new PluginErrorException("Search gallery by title failed", { code });
  }
  logger.debug("Tentative JSON: " + res.body);
  // Was `JSON.parse(res).body` — `res` is the LegacyHttpResult object, not a string. `res.json`
  // (same idiom as chaika.ts) is correct.
  return res.json;
}

/// Every name worth searching on, most trustworthy first: the archive's stored title, then what
/// the file name says, then the title with its `[artist (circle)]` prefix removed (nhentai's search
/// treats the bracketed prefix as noise, so a full name sometimes finds nothing while the bare one
/// lands).
function search_candidates(info: Record<string, any>): string[] {
  let out: string[] = [];
  let push = (value: unknown) => {
    let text = typeof value === "string" ? value.trim() : "";
    // A hash-shaped name (the library's fallback title) matches nothing; searching it wastes a call.
    if (text === "" || /^[0-9a-f]{40}$/i.test(text)) return;
    if (!out.includes(text)) out.push(text);
  };
  push(info["archive_title"]);
  let [stem] = legacyCompat.fileparse(legacyCompat.redis_decode(info["file_path"] ?? ""));
  let fromStem = (stem ?? "").match(/\{(\d*)\}.*$/m);
  if (fromStem) push(fromStem[1]);
  push(stem);
  let bare = (info["archive_title"] ?? "").replace(/^\s*\[[^\]]*\]\s*/, "");
  push(bare);
  return out;
}

async function search_gallery_id(...args: any[]) {
  let [title, ua] = args.slice(0);
  let json = await get_search_json(title, ua);
  let results = json["result"];
  if (results.length > 0) {
    return results[0]["id"];
  }
  return;
}

async function get_json_from_nh(...args: any[]) {
  let [gID, ua] = args.slice(0);
  let logger = legacyCompat.getLogger("nHentai", "plugins");
  let URL = `https://nhentai.net/api/v2/galleries/${gID}`;
  let res = (await ua.get(URL)).result;
  if (res.is_error) {
    let code = res.code;
    throw new PluginErrorException("Error retrieving gallery from nHentai", { code });
  }
  logger.debug("Tentative JSON: " + res.body);
  // Same fix as `get_search_json` above — see that function's own comment.
  return res.json;
}

function get_tags_from_json(...args: any[]) {
  let [json] = args.slice(0);
  let json_tags = json["tags"];
  let tags = [];
  for (let tag of json_tags) {
    let namespace = tag["type"];
    let name = tag["name"];
    if (namespace === "tag") {
      tags.push(name);
    } else {
      tags.push(`${namespace}:${name}`);
    }
  }
  return tags;
}

function get_title_from_json(...args: any[]) {
  let [json, prefer_japanese] = args.slice(0);
  let title = json["title"];
  if (prefer_japanese && title["japanese"]) return title["japanese"];
  // `pretty` is the API's display-normalised title, which drops the `[artist (circle)]` prefix —
  // nhentai's own gallery page shows `english`, so using `pretty` here lost that whole prefix.
  return title["english"] ?? title["pretty"];
}

function get_upload_from_json(...args: any[]) {
  let [json] = args.slice(0);
  return json["upload_date"];
}

async function get_tags_from_nh(...args: any[]) {
  let [gID, ua, add_uploaded, prefer_japanese_title] = args.slice(0);
  let hashdata: Record<string, any> = { tags: "" };
  let json = await get_json_from_nh(gID, ua);
  if (json) {
    let tags = get_tags_from_json(json);
    if (add_uploaded) {
      // Was `upload.join(", ")` — `upload_date` is a single number on the real API, not an array.
      let upload = get_upload_from_json(json);
      tags.push(`timestamp:${upload}`);
    }
    if ((tags.length > 0)) { tags.push(`source:nhentai.net/g/${gID}`); }
    hashdata["tags"] = tags.join(', ');
    hashdata["title"] = get_title_from_json(json, prefer_japanese_title);
  }
  return hashdata;
}
